style.css:
root {
  /* Color Palette */
  soft-pink: #ffd1dc;
  soft-yellow: #fff4cc;
  accent-pink: #f8a1b3;
  accent-yellow: #ffe07a;
  text-dark: #333333;
  text-light: #ffffff;
  background-light: #fffaf0;
  background-dark: #f7eae0;
  border-color: #ffd8e8;
}

body {
  background-color: var(--background-light);
  color: var(--text-dark);
  font-family: 'Arial', sans-serif;
  line-height: 1.6;
  margin: 0;
  padding: 0;
}

header {
  background-color: var(--soft-pink);
  padding: 1rem;
  text-align: center;
  border-bottom: 2px solid var(--border-color);
}

header h1 {
  color: var(--text-dark);
  margin: 0;
  font-size: 2rem;
}

nav {
  background-color: var(--soft-yellow);
  padding: 0.5rem;
  display: flex;
  justify-content: center;
  gap: 1rem;
  border-bottom: 2px solid var(--border-color);
}

nav a {
  color: var(--text-dark);
  text-decoration: none;
  font-weight: bold;
  padding: 0.5rem 1rem;
  border-radius: 5px;
  transition: background-color 0.3s;
}

nav a:hover {
  background-color: var(--accent-pink);
  color: var(--text-light);
}

main {
  padding: 2rem;
  background-color: var(--background-dark);
}

button {
  background-color: var(--accent-yellow);
  color: var(--text-dark);
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 5px;
  font-size: 1rem;
  cursor: pointer;
  transition: background-color 0.3s;
}

button:hover {
  background-color: var(--accent-pink);
  color: var(--text-light);
}

footer {
  background-color: var(--soft-pink);
  text-align: center;
  padding: 1rem;
  border-top: 2px solid var(--border-color);
}

footer p {
  margin: 0;
  color: var(--text-dark);
}
